package com.clothingstore;
import jakarta.persistence.*; import java.math.BigDecimal; import java.util.*;
@Entity @Table(name="orders") public class StoreOrder { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="order_number") private String orderNumber; private String email; private String phone; @Column(name="full_name") private String fullName; @Column(name="address_line") private String addressLine; private String city; @Column(name="postal_code") private String postalCode; @Column(name="payment_method") private String paymentMethod; @Column(name="order_status") private String orderStatus; @Column(name="total_amount") private BigDecimal totalAmount; @OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true) private List<OrderItem> items=new ArrayList<>(); public void addItem(OrderItem i){items.add(i);i.setOrder(this);} public void setOrderNumber(String v){orderNumber=v;} public String getOrderNumber(){return orderNumber;} public void setEmail(String v){email=v;} public void setPhone(String v){phone=v;} public void setFullName(String v){fullName=v;} public void setAddressLine(String v){addressLine=v;} public void setCity(String v){city=v;} public void setPostalCode(String v){postalCode=v;} public void setPaymentMethod(String v){paymentMethod=v;} public void setOrderStatus(String v){orderStatus=v;} public String getOrderStatus(){return orderStatus;} public void setTotalAmount(BigDecimal v){totalAmount=v;} public BigDecimal getTotalAmount(){return totalAmount;} }
